CREATE TABLE `prize_inventories` (
  `id` int(11) NOT NULL,
  `prize_id` int(11) NOT NULL,
  `game_session_id` int(11) NOT NULL COMMENT 'Which game session this prize is in',
  `total_stock` int(11) DEFAULT 1 COMMENT 'Total quantity available',
  `remaining_stock` int(11) DEFAULT 1 COMMENT 'Available - not yet drawn',
  `reserved_count` int(11) DEFAULT 0 COMMENT 'Reserved for orders/withdrawals',
  `drawn_count` int(11) DEFAULT 0 COMMENT 'Already distributed',
  `prize_type` enum('MONEY','PHYSICAL_ITEM','VOUCHER','DIGITAL','EXPERIENCE','SPECIAL') DEFAULT 'MONEY' COMMENT 'Type of prize',
  `item_sku` varchar(50) DEFAULT NULL COMMENT 'Inventory SKU if physical item',
  `can_convert_to_cash` tinyint(1) DEFAULT 0 COMMENT 'Whether player can convert this to money',
  `conversion_rate` float DEFAULT 1 COMMENT 'Conversion multiplier (0.5 = 50% of value)',
  `base_cash_value` bigint(20) DEFAULT NULL COMMENT 'Base cash value (if prize is convertible)',
  `converted_to_cash_count` int(11) DEFAULT 0 COMMENT 'How many converted to cash',
  `is_limited_stock` tinyint(1) DEFAULT 0 COMMENT 'Is this limited edition/',
  `restock_threshold` int(11) DEFAULT NULL COMMENT 'Auto-notify admin when stock reaches this',
  `auto_restock` tinyint(1) DEFAULT 0 COMMENT 'Auto-add stock if runs out',
  `unit_cost` bigint(20) DEFAULT NULL COMMENT 'What the house paid for this prize',
  `total_cost` bigint(20) DEFAULT NULL COMMENT 'Total cost of all stock (auto: total_stock * unit_cost)',
  `total_cash_distributed` bigint(20) DEFAULT 0 COMMENT 'Total cash paid out for this prize',
  `profit_loss` bigint(20) DEFAULT 0 COMMENT 'Revenue - Cost (negative = loss)',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Cấu trúc bảng cho bảng `prize_redemption_histories`
--

CREATE TABLE `prize_redemption_histories` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `session_id` int(11) NOT NULL,
  `session_code` varchar(50) NOT NULL,
  `prize_name` varchar(200) NOT NULL,
  `prize_description` text DEFAULT NULL,
  `prize_value` int(11) DEFAULT NULL,
  `prize_image_url` text DEFAULT NULL,
  `redemption_method` enum('withdrawal','gift_exchange','direct') NOT NULL,
  `withdrawal_id` int(11) DEFAULT NULL,
  `withdrawal_status` enum('pending','approved','rejected','completed') DEFAULT 'pending',
  `withdrawal_amount` int(11) DEFAULT NULL,
  `bank_name` varchar(100) DEFAULT NULL,
  `bank_account` varchar(50) DEFAULT NULL,
  `gift_exchange_id` int(11) DEFAULT NULL,
  `gift_exchange_status` enum('pending','approved','rejected','shipped','delivered') DEFAULT 'pending',
  `recipient_name` varchar(100) DEFAULT NULL,
  `recipient_address` text DEFAULT NULL,
  `recipient_phone` varchar(20) DEFAULT NULL,
  `shipping_provider` varchar(100) DEFAULT NULL,
  `tracking_number` varchar(100) DEFAULT NULL,
  `requested_at` datetime DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `rejected_at` datetime DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `current_status` enum('pending','approved','completed','rejected') DEFAULT 'pending',
  `status_notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

