--
-- Cấu trúc bảng cho bảng `risk_scores`
--

CREATE TABLE `risk_scores` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `risk_score` int(11) DEFAULT 0 COMMENT 'Overall risk%: 0=safe, 100=maximum risk',
  `win_rate_risk` int(11) DEFAULT 0 COMMENT 'Too many wins = higher risk',
  `frequency_risk` int(11) DEFAULT 0 COMMENT 'Playing too frequently consecutive games',
  `device_risk` int(11) DEFAULT 0 COMMENT 'Device fingerprint anomalies',
  `location_risk` int(11) DEFAULT 0 COMMENT 'IP/location changes',
  `timing_risk` int(11) DEFAULT 0 COMMENT 'Unusual play times or patterns',
  `multi_account_risk` int(11) DEFAULT 0 COMMENT 'Detected multi-accounting',
  `behavior_risk` int(11) DEFAULT 0 COMMENT 'Unusual behavior patterns',
  `current_status` enum('SAFE','MONITORING','ELEVATED','SUSPICIOUS','BLOCKED') DEFAULT 'SAFE' COMMENT 'Current risk status',
  `manual_locked` tinyint(1) DEFAULT 0 COMMENT 'Admin manually locked account',
  `locked_reason` text DEFAULT NULL COMMENT 'Why account is locked',
  `locked_until` datetime DEFAULT NULL COMMENT 'When lock expires (null = permanent until admin review)',
  `locked_by_admin` int(11) DEFAULT NULL COMMENT 'Admin user ID who locked',
  `flags_total` int(11) DEFAULT 0 COMMENT 'Total suspicious flags ever raised',
  `flagged_sessions` longtext DEFAULT NULL COMMENT 'Array of flagged session IDs (last 20)' CHECK (json_valid(`flagged_sessions`)),
  `last_flagged` datetime DEFAULT NULL COMMENT 'Last time flagged',
  `last_reviewed` datetime DEFAULT NULL COMMENT 'Last admin review',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

