--
-- Cấu trúc bảng cho bảng `transaction_ledger`
--

CREATE TABLE `transaction_ledger` (
  `id` bigint(20) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT 'User making the transaction',
  `transaction_type` enum('GAME_WIN','GAME_LOSS','PRIZE_DRAWN','PRIZE_CONVERTED','WITHDRAWAL_REQUEST','WITHDRAWAL_APPROVED','WITHDRAWAL_REJECTED','WITHDRAWAL_PAID','ADMIN_ADJUSTMENT','REFERRAL_BONUS','DAILY_REWARD','LEVEL_UP_REWARD','PROMOTION','REFUND','CHARGEBACK','LOCKED_HOLD','LOCKED_RELEASE') NOT NULL COMMENT 'Type of transaction',
  `amount` bigint(20) NOT NULL COMMENT 'Amount (can be negative for debits)',
  `balance_before` bigint(20) NOT NULL COMMENT 'Total balance before this transaction',
  `balance_after` bigint(20) NOT NULL COMMENT 'Total balance after this transaction',
  `available_before` bigint(20) DEFAULT NULL COMMENT 'Available balance before',
  `available_after` bigint(20) DEFAULT NULL COMMENT 'Available balance after',
  `pending_before` bigint(20) DEFAULT NULL COMMENT 'Pending balance before',
  `pending_after` bigint(20) DEFAULT NULL COMMENT 'Pending balance after',
  `locked_before` bigint(20) DEFAULT NULL COMMENT 'Locked balance before',
  `locked_after` bigint(20) DEFAULT NULL COMMENT 'Locked balance after',
  `game_session_id` int(11) DEFAULT NULL COMMENT 'If game result, link to GameSession',
  `withdrawal_id` int(11) DEFAULT NULL COMMENT 'If withdrawal related, link to Withdrawal',
  `prize_id` int(11) DEFAULT NULL COMMENT 'If prize related, link to Prize',
  `description` text DEFAULT NULL COMMENT 'Human-readable description',
  `metadata` longtext DEFAULT NULL COMMENT 'Extra data: game_result_details, payment_proof, etc' CHECK (json_valid(`metadata`)),
  `created_by` varchar(100) DEFAULT NULL COMMENT 'Who created this: user_id, admin_id, system, etc',
  `ip_address` varchar(255) DEFAULT NULL COMMENT 'IP where transaction originated',
  `user_agent` text DEFAULT NULL COMMENT 'Browser info at transaction time',
  `transaction_hash` varchar(64) DEFAULT NULL COMMENT 'SHA256 of all transaction details for verification',
  `created_at` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

