  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `current_level` int(11) DEFAULT 1 COMMENT 'Current level (1-100)',
  `current_xp` int(11) DEFAULT 0 COMMENT 'XP in current level',
  `xp_required_next_level` int(11) DEFAULT 1000 COMMENT 'XP needed to reach next level',
  `total_xp` bigint(20) DEFAULT 0 COMMENT 'Lifetime total XP',
  `tier` enum('BRONZE','SILVER','GOLD','PLATINUM','DIAMOND','LEGENDARY') DEFAULT 'BRONZE',
  `badges` longtext DEFAULT NULL COMMENT 'Array of earned badge IDs' CHECK (json_valid(`badges`)),
  `current_streak` int(11) DEFAULT 0 COMMENT 'Current play/win streak',
  `max_streak` int(11) DEFAULT 0 COMMENT 'Best streak ever',
  `last_play_date` datetime DEFAULT NULL COMMENT 'Last time played (for streak tracking)',
  `daily_tasks_completed` int(11) DEFAULT 0 COMMENT 'Tasks completed today',
  `daily_reward_claimed` tinyint(1) DEFAULT 0 COMMENT 'Already claimed daily reward today',
  `daily_reward_last_claimed` datetime DEFAULT NULL COMMENT 'When daily reward was last claimed',
  `consecutive_days` int(11) DEFAULT 0 COMMENT 'Consecutive days of login/play',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

