--
-- Cấu trúc bảng cho bảng `wallets`
--

CREATE TABLE `wallets` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT 'User ID - one wallet per user',
  `total_balance` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Total balance = available + pending + locked',
  `available_balance` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Can withdraw or use immediately',
  `pending_balance` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Waiting for approval (e.g., withdrawal pending)',
  `locked_balance` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Locked for game in progress or other holds',
  `last_updated_at` datetime DEFAULT NULL COMMENT 'Last update timestamp',
  `updated_by` varchar(100) DEFAULT NULL COMMENT 'Who/what updated the balance (admin_user_id, system, game_id, etc)',
  `version` int(11) DEFAULT 1 COMMENT 'Optimistic locking version for concurrent updates',
  `integrity_hash` varchar(64) DEFAULT NULL COMMENT 'SHA256 of (user_id + total + available + pending + locked) for verification',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

