--
-- Cấu trúc bảng cho bảng `withdrawals`
--

CREATE TABLE `withdrawals` (
  `id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL,
  `bank_name` varchar(100) NOT NULL,
  `account_number` varchar(50) NOT NULL,
  `account_holder` varchar(100) NOT NULL,
  `status` enum('pending','approved','rejected') DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `customer_name` varchar(100) DEFAULT NULL COMMENT 'Customer name from withdrawal form',
  `customer_phone` varchar(20) DEFAULT NULL COMMENT 'Customer phone number',
  `customer_email` varchar(100) DEFAULT NULL COMMENT 'Customer email address',
  `session_code` varchar(50) DEFAULT NULL COMMENT 'Link to game session code',
  `selected_box_number` int(11) DEFAULT NULL COMMENT 'Which box (1, 2, 3) player selected',
  `prize_name` varchar(255) DEFAULT NULL COMMENT 'Name of prize from selected box',
  `prize_value` decimal(15,2) DEFAULT NULL COMMENT 'Value of prize in cash',
  `selected_at` datetime DEFAULT NULL COMMENT 'When player selected the box',
  `player_contact` longtext DEFAULT NULL COMMENT 'Player contact info {phone, email, name}' CHECK (json_valid(`player_contact`)),
  `box_selection_snapshot` longtext DEFAULT NULL COMMENT 'Full box data at time of selection' CHECK (json_valid(`box_selection_snapshot`)),
  `withdraw_method` enum('bank_transfer','momo','zalopay') DEFAULT 'bank_transfer' COMMENT 'Method: bank_transfer, momo, or zalopay',
  `request_source` enum('game','result','admin','other') DEFAULT 'game' COMMENT 'Where request came from: game page or result page',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `customer_ip` varchar(50) DEFAULT NULL,
  `customer_cookie_id` varchar(255) DEFAULT NULL,
  `withdrawal_type` varchar(50) DEFAULT 'cash_prize',
  `requested_by` varchar(100) DEFAULT NULL,
  `requested_at` datetime DEFAULT NULL,
  `approved_by` varchar(100) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `rejected_by` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

